1#include <iostream>
2#include <vector>
3
4using namespace std;
5
6class BinaryTree {
7public:
8    BinaryTree() {}
9
10    // Calculate the index of a node's parent
11    int parent(int index) {
12        return (index - 1) / 2;
13    }
14
15    // Calculate the index of a node's left child
16    int left_child(int index) {
17        return 2 * index + 1;
18    }
19
20    // Calculate the index of a node's right child
21    int right_child(int index) {
22        return 2 * index + 2;
23    }
24
25    // Check if a node at a given index has a parent
26    bool has_parent(int index) {
27        return parent(index) >= 0;
28    }
29
30    // Check if a node at a given index has a left child
31    bool has_left_child(int index) {
32        return left_child(index) < arr.size();
33    }
34
35    // Check if a node at a given index has a right child
36    bool has_right_child(int index) {
37        return right_child(index) < arr.size();
38    }
39
40    // Add a new element to the binary tree 
41    void insert(int value) {
42        arr.push_back(value);
43    }
44
45    // Print the tree contents
46    void print_tree() {
47        for (int value : arr) {
48            cout << value << " ";
49        }
50        cout << endl;
51    }
52
53    // Access an element at a specific index
54    int get_value_at(int index) {
55        return arr[index];
56    }
57
58private:
59    vector<int> arr;
60};
61
62int main() {
63
64    BinaryTree bt;
65
66    // Insert elements into the binary tree
67    for (int i = 0; i < 10; i++) {
68        bt.insert(i);
69    }
70
71    // Display binary tree
72    bt.print_tree();
73    cout << endl;
74
75    // Check some relationships
76    int index = 3;
77    if (bt.has_parent(index)) {
78        cout << "Parent of node at index " << index << ": " << bt.get_value_at(bt.parent(index)) << endl;
79    }
80
81    if (bt.has_left_child(index)) {
82        cout << "Left child of node at index " << index << ": " << bt.get_value_at(bt.left_child(index)) << endl;
83    }
84
85    if (bt.has_right_child(index)) {
86        cout << "Right child of node at index " << index << ": " << bt.get_value_at(bt.right_child(index)) << endl;
87    }
88
89    return 0;
90}
